package com.bank.portal.service;
import com.bank.portal.domain.*; import com.bank.portal.repository.*; import com.bank.portal.web.ApiDtos.*; import java.time.*; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class CardApplicationService { private final CustomerUserRepository users; private final CustomerCardRequestRepository requests;
 private Customer customer(String username){return users.findByUsernameOrCustomerEmail(username,username).orElseThrow(()->new IllegalArgumentException("Customer not found")).getCustomer();}
 @Transactional public CardApplicationView submit(String username,CardApplicationInput r){Customer c=customer(username);if(requests.existsByCustomerIdAndCardTypeAndStatus(c.getId(),r.cardType(),CustomerCardRequestStatus.PENDING))throw new IllegalStateException("A pending request already exists for this card type");CustomerCardRequest q=new CustomerCardRequest();q.setCustomer(c);q.setCardType(r.cardType());q.setStatus(CustomerCardRequestStatus.PENDING);return view(requests.save(q));}
 public List<CardApplicationView> mine(String u){return requests.findByCustomerIdOrderByCreatedAtDesc(customer(u).getId()).stream().map(this::view).toList();} public List<CardApplicationView> pending(){return requests.findByStatusInOrderByCreatedAtAsc(java.util.List.of(CustomerCardRequestStatus.PENDING,CustomerCardRequestStatus.APPROVED)).stream().map(this::view).toList();} @Transactional public void markIssued(Long customerId,CardType type){requests.findFirstByCustomerIdAndCardTypeAndStatusOrderByCreatedAtDesc(customerId,type,CustomerCardRequestStatus.APPROVED).ifPresent(q->q.setStatus(CustomerCardRequestStatus.ISSUED));}
 @Transactional public CardApplicationView review(Long id,CardApplicationReview r,String staff){CustomerCardRequest q=requests.findById(id).orElseThrow(()->new IllegalArgumentException("Card request not found"));if(q.getStatus()!=CustomerCardRequestStatus.PENDING)throw new IllegalStateException("Request already reviewed");q.setStatus(r.status());q.setReviewComment(r.comment());q.setReviewedBy(staff);q.setReviewedAt(LocalDateTime.now());return view(q);} private CardApplicationView view(CustomerCardRequest q){return new CardApplicationView(q.getId(),q.getCustomer().getId(),q.getCustomer().getName(),q.getCardType(),q.getStatus().name(),q.getReviewComment());}}
